// Website template data. The JSON is generated by the catalog's Python reader
// (the same reader the API uses); do not normalize or patch fields here.
import data from "../data/templates.json";

export {
  APP_URL,
  USE_IT_FOR_FREE_LABEL,
  useItForFreeUrl,
} from "./useItForFree";

export type WebsiteTemplate = (typeof data.templates)[number];
export type WebsiteAuthor = (typeof data.authors)[number];

export const templates: WebsiteTemplate[] = data.templates;
export const authors: WebsiteAuthor[] = data.authors;

export const templateByKey = (key: string): WebsiteTemplate | undefined =>
  templates.find((template) => template.key === key);

// Membership comes from each template's author reference, not a copied list.
export const templatesByAuthor = (authorId: string): WebsiteTemplate[] =>
  templates.filter((template) => template.author.id === authorId);
